function tinted(img,color){ // pre-tinted copy for hurt flash
  const c=document.createElement("canvas");c.width=img.naturalWidth||1;c.height=img.naturalHeight||1;
  const g=c.getContext("2d");g.drawImage(img,0,0);
  g.globalCompositeOperation="source-atop";g.fillStyle=color;g.fillRect(0,0,c.width,c.height);
  return c;
}
