/* ================= AUDIO ================= */
let AC=null,master=null,soundOn=true,musicTimer=null;
function resumeAudio(){try{if(!AC){AC=new (window.AudioContext||window.webkitAudioContext)();master=AC.createGain();master.gain.value=0.5;master.connect(AC.destination);}if(AC.state==="suspended")AC.resume();}catch(e){}}
function tone(f,d,type,v,slideTo){
  if(!soundOn||!AC)return;type=type||"square";v=v||0.16;
  try{const o=AC.createOscillator(),g=AC.createGain();
  o.type=type;o.frequency.setValueAtTime(f,AC.currentTime);
  if(slideTo)o.frequency.exponentialRampToValueAtTime(slideTo,AC.currentTime+d);
  g.gain.setValueAtTime(v,AC.currentTime);g.gain.exponentialRampToValueAtTime(0.0008,AC.currentTime+d);
  o.connect(g);g.connect(master);o.start();o.stop(AC.currentTime+d);}catch(e){}
}
function noise(d,v,hp){
  if(!soundOn||!AC)return;v=v||0.22;hp=hp||800;
  try{const n=AC.createBufferSource(),buf=AC.createBuffer(1,AC.sampleRate*d,AC.sampleRate);
  const dt=buf.getChannelData(0);for(let i=0;i<dt.length;i++)dt[i]=Math.random()*2-1;
  n.buffer=buf;const f=AC.createBiquadFilter();f.type="highpass";f.frequency.value=hp;
  const g=AC.createGain();g.gain.setValueAtTime(v,AC.currentTime);g.gain.exponentialRampToValueAtTime(0.001,AC.currentTime+d);
  n.connect(f);f.connect(g);g.connect(master);n.start();n.stop(AC.currentTime+d);}catch(e){}
}
