/* ================= NET: Socket.IO room relay ================= */
let socket=null,online=false,mySeat=1,inRoom=false,roomId="";
function netStat(t,show){const el=document.getElementById("netStat");el.classList.toggle("hide",!show);el.textContent=t;}
function ensureSocket(){
  if(socket)return socket;
  socket=io();
  socket.on("connect",()=>netStat("📶 已连接服务器",true));
  socket.on("connect_error",()=>{netStat("📶 服务器连接失败",true);toast("无法连接服务器：请刷新或稍后再试（免费服务器冷启动约需1分钟）");});
  socket.on("roomUpdate",d=>{
    if(d&&d.count>=2){document.getElementById("pc2s").textContent="已加入！";
      document.getElementById("btnReady").classList.remove("hide");
      if(mySeat===1){toast("好友已加入！双方点击准备即可开战");SFX.cheer();}}
  });
  socket.on("readyState",d=>{
    try{
      const foeReady = mySeat===1 ? (d.p2||d.seat2||d[2]) : (d.p1||d.seat1||d[1]);
      if(foeReady){document.getElementById(mySeat===1?"pc2":"pc1").classList.add("rdy");
        document.getElementById(mySeat===1?"pc2s":"pc1s").textContent="已准备 ✔";}
    }catch(e){}
  });
  socket.on("startGame",()=>{beginBattle("online");});
  socket.on("data",onNet);
  socket.on("rematchAsk",()=>toast("对方想再来一局！点击「再来一局」应战"));
  socket.on("peerLeft",()=>{
    online=false;inRoom=false;
    if(inBattle){quitBattle();showScr("scrMenu");}
    toast("对方已离开房间");
    netStat("📶 对方已断开",true);
  });
  return socket;
}
function hostRoom(){
  const s=ensureSocket();
  s.emit("createRoom",res=>{
    if(!res||!res.ok){toast("创建房间失败，请重试");return;}
    roomId=res.roomId;mySeat=res.seat||1;online=true;inRoom=true;
    showScr("scrRoom");
    document.getElementById("roomCode").textContent=roomId;
    document.getElementById("pc1s").textContent="已就位";
    document.getElementById("pc2s").textContent="等待加入…";
    resetReadyUI();
    netStat("📶 房间已开启",true);
  });
}
function joinRoom(code){
  const s=ensureSocket();
  s.emit("joinRoom",code,res=>{
    if(!res||!res.ok){toast(res&&res.msg?res.msg:"没有找到该房间，请确认房间号");return;}
    roomId=res.roomId;mySeat=res.seat||2;online=true;inRoom=true;
    showScr("scrRoom");
    document.getElementById("roomCode").textContent=roomId;
    document.getElementById("pc1s").textContent="房主已就位";
    document.getElementById("pc2s").textContent="已加入！";
    resetReadyUI();
    document.getElementById("btnReady").classList.remove("hide");
    toast("已进入房间！点击准备开战");
    netStat("📶 已加入房间",true);
  });
}
function resetReadyUI(){
  document.getElementById("pc1").classList.remove("rdy");
  document.getElementById("pc2").classList.remove("rdy");
  const b=document.getElementById("btnReady");
  b.textContent="✅ 准备！";
  b.classList.toggle("hide",mySeat===1);
}
function send(o){if(online&&socket)try{socket.emit("data",o);}catch(e){}}
function shareRoom(){
  const url=location.origin+location.pathname+"?room="+roomId;
  const data={title:"梅开格斗：开放之战",text:"我在梅州开放大学·荣耀擂台等你！房间号 "+roomId+"，微信点开即可加入对战！",url};
  if(navigator.share){navigator.share(data).catch(()=>{});}
  else{try{navigator.clipboard.writeText(data.text+" "+url);}catch(e){}toast("邀请链接已复制，去微信粘贴给好友吧！");}
}
function onNet(m){
  if(!m||!m.t)return;
  switch(m.t){
    case "st":if(foe){foe.nx=m.x;foe.ny=m.y;foe.nf=m.f;foe.hp=m.hp;foe.en=m.en;foe.blocking=m.b;
      if(m.a&&m.a.atk&&foe.atk<=0)remoteAnim(foe,m.a.ty);}break;
    case "hit":applyHitToMe(m);break;
    case "proj":spawnProj(foe,m.kind,true,m.x,m.y,m.dir);break;
    case "fx":remoteFx(m);break;
    case "ko":if(inBattle)roundEnd(me);break;
    case "round":if(mySeat!==1)setupRound(m.n);break;
    case "timer":timer=m.v;if(timer<=5&&timer>0)SFX.count();break;
    case "matchend":if(mySeat!==1)matchEnd(m.w);break;
  }
}

/* ================= GAME STATE ================= */
let mode="solo",inBattle=false,raf=null,lastT=0,frame=0;
let me=null,foe=null,timer=99,tAcc=0,roundN=1,wins=[0,0],paused=0,hitstop=0,slowmo=0;
let fxList=[],projs=[],shake=0,bann=null,flash=0,cine=null,sendAcc=0,zoom=0;
let stats={dmg:0,maxCombo:0};
let cheerGirls=[];

function mkF(ci,x,facing,local){
  return {ci,x,y:GROUND,vx:0,vy:0,facing,local,
   hp:100,en:0,onG:true,stun:0,inv:0,blocking:false,
   atk:0,atkDur:1,atkType:null,hitDone:false,hitN:0,cool:0,dash:0,chain:0,chainT:0,
   cdS1:0,cdS2:0,cdDG:0,combo:0,comboT:0,bubble:"",bubT:0,
   nx:x,ny:GROUND,nf:facing,koT:0};
}
function myCharIndex(){return mode==="online"?(mySeat===1?0:1):0;}
function beginBattle(m){
  mode=m;inBattle=true;wins=[0,0];stats={dmg:0,maxCombo:0};
  showScr(null);
  document.getElementById("ctlL").classList.remove("hide");
  document.getElementById("ctlR").classList.remove("hide");
  document.getElementById("sndTog").classList.remove("hide");
  initCheer();
  setupRound(1);
  startMusic();
  if(innerHeight>innerWidth)document.getElementById("rotateHint").classList.remove("hide");
  if(!raf){lastT=performance.now();raf=requestAnimationFrame(loop);}
}
function setupRound(n){
  roundN=n;timer=99;tAcc=0;fxList=[];projs=[];shake=0;flash=0;cine=null;hitstop=0;slowmo=0;paused=0;zoom=0;
  const mi=myCharIndex();
  me=mkF(mi, mi===0?VW*0.27:VW*0.73, mi===0?1:-1,true);
  foe=mkF(1-mi, mi===0?VW*0.73:VW*0.27, mi===0?-1:1,false);
  banner("ROUND "+n,1000,"#7fc2ff");
  setTimeout(()=>{banner("FIGHT!",900,"#ff4d4d");SFX.fire();},1050);
  me.bubble=CHARS[me.ci].intro;me.bubT=1800;
  if(mode==="online"&&mySeat===1)send({t:"round",n});
}
function quitBattle(){
  inBattle=false;stopMusic();
  document.getElementById("ctlL").classList.add("hide");
  document.getElementById("ctlR").classList.add("hide");
}
function roundEnd(winner){
  if(paused===2)return;paused=2;
  SFX.ko();banner("K.O. !",1600,"#ffd23a");shake=26;slowmo=1100;zoom=1;
  const loser=(winner===me)?foe:me;loser.koT=1;
  const wIdx=(winner===me)?0:1;wins[wIdx]++;
  setTimeout(()=>{
    zoom=0;
    if(wins[0]>=2||wins[1]>=2){
      const winCi=(wins[0]>=2)?me.ci:foe.ci;
      if(mode==="online"&&mySeat===1)send({t:"matchend",w:winCi});
      matchEnd(winCi);
    } else setupRound(roundN+1);
  },2100);
}
function matchEnd(winCi){
  quitBattle();
  const c=CHARS[winCi];
  document.getElementById("resBody").src=c.sprSrc;
  document.getElementById("resTitle").textContent=(winCi===me.ci)?"VICTORY!":"DEFEAT…";
  document.getElementById("resText").textContent=c.name+"："+c.winLine;
  document.getElementById("resStats").textContent="本局数据　总伤害 "+stats.dmg+"　最高连击 "+stats.maxCombo+" COMBO　比分 "+wins[0]+" : "+wins[1];
  showScr("scrRes");
  (winCi===me.ci)?SFX.win():SFX.lose();
}

/* ================= FX ================= */
function banner(text,dur,color){bann={text,t:dur,d:dur,color};}
function spark(x,y,color,n){n=n||10;for(let i=0;i<n;i++)fxList.push({t:"p",x,y,vx:(Math.random()-0.5)*11,vy:-Math.random()*9,life:430,color});}
function ring(x,y,color,big){fxList.push({t:"r",x,y,r:big?16:6,grow:big?0.55:0.2,life:big?520:360,color});}
function dmgText(x,y,v,crit){fxList.push({t:"d",x,y,v:"-"+v,life:780,crit});}
function starFx(x,y,col){fxList.push({t:"s",x,y,vx:(Math.random()-0.5)*8,vy:-Math.random()*10-2,rot:Math.random()*6,life:660,col:col||"#ffd23a"});}
function dust(x,y,n){n=n||6;for(let i=0;i<n;i++)fxList.push({t:"u",x:x+(Math.random()-0.5)*26,y,vx:(Math.random()-0.5)*3,vy:-Math.random()*2,life:380});}
function slash(x,y,dir,col){fxList.push({t:"sl",x,y,dir,life:240,col});}
function remoteFx(m){
  if(m.k==="spark")spark(m.x,m.y,m.c,m.n);
  else if(m.k==="cine")startCine(CHARS[m.ci],false);
  else if(m.k==="sfx"&&SFX[m.n])SFX[m.n]();
  else if(m.k==="bub"&&foe){foe.bubble=m.txt;foe.bubT=1100;}
}

/* ================= PROJECTILES ================= */
function spawnProj(owner,kind,visualOnly,x,y,dir){
  const c=CHARS[owner.ci];
  const p={owner,ci:owner.ci,kind,visual:!!visualOnly,
    x:(x!==undefined)?x:owner.x+owner.facing*46,
    y:(y!==undefined)?y:owner.y-92,
    dir:(dir!==undefined)?dir:owner.facing,
    life:kind==="ult"?1400:1100, hit:false, trail:0};
  p.vx=p.dir*(kind==="ult"?7.5:9.5);
  projs.push(p);
  if(owner.local&&mode==="online")send({t:"proj",kind,x:p.x,y:p.y,dir:p.dir});
  return p;
}
function updateProjs(dt){
  for(const p of projs){
    p.life-=dt;p.x+=p.vx;p.trail+=dt;
    // trail particles
    if(p.trail>40){p.trail=0;
      fxList.push({t:"p",x:p.x-p.dir*12,y:p.y+(Math.random()-0.5)*16,vx:-p.dir*1.5,vy:(Math.random()-0.5)*2,life:300,color:CHARS[p.ci].spark});}
    if(p.x<-80||p.x>VW+80)p.life=0;
    // collision: only my own real projectiles damage foe
    if(!p.visual&&!p.hit&&p.owner===me&&foe&&foe.inv<=0){
      const R=p.kind==="ult"?70:34;
      if(Math.abs(p.x-foe.x)<R+24&&Math.abs(p.y-(foe.y-86))<R+50){
        p.hit=true;p.life=Math.min(p.life,120);
        const blocked=foe.blocking&&(foe.facing!==p.dir);
        const base=p.kind==="ult"?30:13;
        dealDamage(me,foe,base,blocked,p.kind==="ult",p.kind==="ult"?12:6,p.kind==="ult"?-9:-4,p.kind==="ult"?700:380);
      }
    }
    // solo: AI projectiles damage me
    if(!p.visual&&!p.hit&&mode!=="online"&&p.owner===foe&&me&&me.inv<=0){
      const R=p.kind==="ult"?70:34;
      if(Math.abs(p.x-me.x)<R+24&&Math.abs(p.y-(me.y-86))<R+50){
        p.hit=true;p.life=Math.min(p.life,120);
        const blocked=me.blocking&&(me.facing!==p.dir);
        dealDamageLocal(foe,me,p.kind==="ult"?30:13,blocked,p.kind==="ult",p.dir);
      }
    }
  }
  projs=projs.filter(p=>p.life>0);
}
function drawProj(p){
  const c=CHARS[p.ci],t=frame/60;
  ctx.save();ctx.translate(p.x,p.y);
  if(p.kind==="ult"){
    // dragon/beam head
    ctx.scale(p.dir,1);
    const grd=ctx.createRadialGradient(0,0,6,0,0,64);
    grd.addColorStop(0,"#fff");grd.addColorStop(0.35,c.spark);grd.addColorStop(1,c.glow+"0)");
    ctx.fillStyle=grd;ctx.beginPath();ctx.arc(0,0,64,0,7);ctx.fill();
    ctx.strokeStyle=c.main;ctx.lineWidth=5;
    for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(-20-i*26,Math.sin(t*10+i)*14,30-i*6,0,7);ctx.stroke();}
    ctx.fillStyle="#fff";ctx.beginPath();ctx.arc(14,-8,6,0,7);ctx.fill(); // eye
  } else {
    const grd=ctx.createRadialGradient(0,0,3,0,0,30);
    grd.addColorStop(0,"#fff");grd.addColorStop(0.4,c.spark);grd.addColorStop(1,c.glow+"0)");
    ctx.fillStyle=grd;ctx.beginPath();ctx.arc(0,0,30,0,7);ctx.fill();
    ctx.strokeStyle=c.main;ctx.lineWidth=3;
    ctx.beginPath();ctx.arc(0,0,18+4*Math.sin(t*16),0,7);ctx.stroke();
  }
  ctx.restore();
}

/* ================= COMBAT ================= */
const MOVES={
 LP1:{dmg:5,dur:170,hitAt:80,range:64,stun:230,kb:3,vy:-1.5,sfx:"punch",lean:0.16,lunge:8},
 LP2:{dmg:6,dur:180,hitAt:80,range:68,stun:250,kb:3.5,vy:-2,sfx:"punch",lean:0.2,lunge:12},
 LP3:{dmg:9,dur:240,hitAt:110,range:76,stun:340,kb:7,vy:-4,sfx:"heavy",lean:0.26,lunge:18},
 HP:{dmg:12,dur:300,hitAt:160,range:74,stun:380,kb:5,vy:-8,sfx:"heavy",lean:0.24,lunge:10,cool:560},
 KK:{dmg:10,dur:280,hitAt:130,range:96,stun:320,kb:7,vy:-3,dash:6,sfx:"kick",lean:0.34,lunge:24,cool:450},
 SHO:{dmg:14,dur:420,hitAt:120,range:70,stun:520,kb:5,vy:-11,sfx:"shoryu",lean:-0.2,rise:true},
 SPIN:{dmg:4,dur:520,hitAt:100,range:80,stun:200,kb:4,vy:-2,dash:9,sfx:"spin",lean:0.1,multi:3},
 ULTM:{dmg:0,dur:600,hitAt:9999,range:0,stun:0,kb:0,vy:0,sfx:"ultBoom",lean:0.3}
};
function curMove(f){return MOVES[f.atkType]||MOVES.LP1;}
function startMove(f,type){
  const mv=MOVES[type];
  f.atkType=type;f.atk=mv.dur;f.atkDur=mv.dur;f.hitDone=false;f.hitN=0;
  if(mv.dash)f.dash=f.facing*mv.dash;
  if(mv.rise&&f.onG){f.vy=-12.5;f.onG=false;}
  if(f.local){SFX[mv.sfx]();if(mode==="online")send({t:"fx",k:"sfx",n:mv.sfx});}
}
function tryAction(f,key){
  if(f.stun>0||f.blocking||f.koT)return;
  const c=CHARS[f.ci];
  if(key==="LP"){
    if(f.atk>0){ // chain window
      if(f.chain<2&&f.atk<f.atkDur*0.55&&(f.atkType==="LP1"||f.atkType==="LP2")){f.chain++;startMove(f,"LP"+(f.chain+1));}
      return;
    }
    if(f.cool>0)return;f.chain=0;f.cool=240;startMove(f,"LP1");return;
  }
  if(f.atk>0)return;
  if(key==="HP"){if(f.cool>0)return;f.cool=MOVES.HP.cool;startMove(f,"HP");}
  else if(key==="KK"){if(f.cool>0)return;f.cool=MOVES.KK.cool;startMove(f,"KK");dust(f.x,GROUND,5);}
  else if(key==="S1"){
    if(f.cdS1>0)return;f.cdS1=2600;
    startMove(f,"LP2"); // throw pose
    spawnProj(f,"orb");
    f.bubble=c.s1+"！";f.bubT=1000;
    if(f.local){SFX.fire();if(mode==="online"){send({t:"fx",k:"sfx",n:"fire"});send({t:"fx",k:"bub",txt:f.bubble});}}
  }
  else if(key==="S2"){
    if(f.cdS2>0)return;f.cdS2=4200;f.inv=Math.max(f.inv,300);
    startMove(f,f.ci===0?"SHO":"SPIN");
    f.bubble=c.s2+"！";f.bubT=1000;
    if(f.local&&mode==="online")send({t:"fx",k:"bub",txt:f.bubble});
  }
  else if(key==="ULT"){
    if(f.en<100)return;f.en=0;
    startMove(f,"ULTM");
    startCine(c,true);
    if(f.local&&mode==="online")send({t:"fx",k:"cine",ci:f.ci});
  }
}
function startCine(c,mine){
  cine={c,t:1200,d:1200};paused=1;SFX.charge();
  setTimeout(()=>{
    paused=0;cine=null;flash=340;shake=28;slowmo=520;SFX.ultBoom();
    banner(c.ultLine,1500,"#ffd23a");
    const owner=(c===CHARS[me.ci])?me:foe;
    if(owner===me||mode!=="online")spawnProj(owner,"ult");
    else spawnProj(owner,"ult",true); // remote spawns its own real one on its side
  },1200);
}
function meleeCheck(f,o){
  if(f.atk<=0||f.atkType==="ULTM")return;
  const mv=curMove(f);
  const elapsed=f.atkDur-f.atk;
  if(mv.multi){ // spin: 3 hits
    const seg=mv.dur/(mv.multi+1);
    const n=Math.floor(elapsed/seg);
    if(n>f.hitN&&n<=mv.multi){f.hitN=n;tryLand(f,o,mv,true);}
    return;
  }
  if(f.hitDone||elapsed<mv.hitAt)return;
  tryLand(f,o,mv,false);
}
function tryLand(f,o,mv,multi){
  const dx=(o.x-f.x)*f.facing;
  const inY=Math.abs((o.y-86)-(f.y-86))<108;
  if(dx>-16&&dx<mv.range&&inY&&o.inv<=0){
    if(!multi)f.hitDone=true;
    const blocked=o.blocking&&(o.facing!==f.facing)&&o.onG;
    let dmg=mv.dmg+Math.floor(Math.random()*2);
    if(f.combo>=3&&!blocked)dmg+=2;
    dealDamage(f,o,dmg,blocked,false,f.facing*mv.kb,mv.vy,blocked?120:mv.stun);
  }
}
function dealDamage(f,o,dmg,blocked,isUlt,kbx,kby,stun){
  if(blocked)dmg=Math.max(1,Math.round(dmg*0.2));
  f.combo++;f.comboT=1000;
  if(f===me){stats.dmg+=dmg;stats.maxCombo=Math.max(stats.maxCombo,f.combo);}
  const crit=isUlt||f.combo>=5;
  if(mode==="online"&&f.local){
    send({t:"hit",dmg,kb:kbx,vy:kby,stun,blocked,crit,sp:isUlt});
    o.hp=Math.max(0,o.hp-dmg); // prediction
    hitVisual(o,dmg,blocked,crit,f);
  } else {
    o.hp=Math.max(0,o.hp-dmg);
    if(!blocked){o.stun=stun;o.vx=kbx;o.vy=kby;o.onG=false;}
    else o.stun=120;
    hitVisual(o,dmg,blocked,crit,f);
    if(o.hp<=0)roundEnd(f);
  }
  o.inv=multiSafe(f)?80:200;
  f.en=Math.min(100,f.en+(isUlt?0:9));
  o.en=Math.min(100,o.en+(blocked?3:6));
  comboShout(f);
}
function multiSafe(f){return f.atkType==="SPIN";}
function dealDamageLocal(f,o,dmg,blocked,isUlt,dir){ // solo AI projectile on me
  if(blocked)dmg=Math.max(1,Math.round(dmg*0.2));
  o.hp=Math.max(0,o.hp-dmg);
  if(!blocked){o.stun=isUlt?700:380;o.vx=dir*(isUlt?12:6);o.vy=isUlt?-9:-4;o.onG=false;}
  o.inv=200;hitVisual(o,dmg,blocked,isUlt,f);
  if(o.hp<=0)roundEnd(f);
}
function hitVisual(o,dmg,blocked,crit,f){
  const c=CHARS[f.ci];
  spark(o.x,o.y-100,blocked?"#9fd4ff":c.spark,crit?22:11);
  ring(o.x,o.y-100,blocked?"#7fc2ff":"#fff",crit);
  slash(o.x,o.y-100,f.facing,c.main);
  dmgText(o.x,o.y-200,dmg,crit);
  if(crit){for(let i=0;i<6;i++)starFx(o.x,o.y-100,c.main);zoom=crit?0.6:0;}
  o.hurtT=240;
  hitstop=crit?130:65;shake=crit?20:9;
  blocked?SFX.block():(crit?SFX.hit2():SFX.hit());
  if(mode==="online"&&f.local)send({t:"fx",k:"spark",x:o.x,y:o.y-100,c:c.spark,n:crit?22:11});
  if(Math.random()<0.3&&f.local){f.bubble=["哈哈哈！","看招！","就这？","笑容暴击！","下一个！"][Math.floor(Math.random()*5)];f.bubT=900;
    if(mode==="online")send({t:"fx",k:"bub",txt:f.bubble});}
}
function applyHitToMe(m){
  if(!me||paused===2)return;
  me.hp=Math.max(0,me.hp-m.dmg);
  if(!m.blocked){me.stun=m.stun;me.vx=m.kb;me.vy=m.vy;me.onG=false;}
  else me.stun=120;
  me.inv=200;me.en=Math.min(100,me.en+(m.blocked?3:6));me.hurtT=240;
  spark(me.x,me.y-100,"#ff9d6b",m.crit?22:11);dmgText(me.x,me.y-200,m.dmg,m.crit);
  hitstop=m.crit?130:65;shake=m.crit?20:9;m.blocked?SFX.block():SFX.hit();
  if(me.hp<=0){send({t:"ko"});roundEnd(foe);}
}
function comboShout(f){
  const c=f.combo;
  if(c===3)banner("Good!",520,"#7fe27f");
  else if(c===5)banner("Great!",560,"#5ec8ff");
  else if(c===7)banner("Excellent!",600,"#ffb02e");
  else if(c===10){banner("SUPER COMBO!",900,"#ff5a3a");shake=22;SFX.cheer();}
  if(c>=3&&f.local)SFX.combo();
}
function remoteAnim(f,ty){
  if(!ty||!MOVES[ty])return;
  f.atkType=ty;f.atk=MOVES[ty].dur;f.atkDur=MOVES[ty].dur;f.hitDone=true;f.hitN=99;
}

/* ================= AI ================= */
let aiT=0,aiMove=0;
function aiUpdate(f,o,dt){
  aiT-=dt;const dx=o.x-f.x,adx=Math.abs(dx);
  if(f.atk<=0)f.facing=dx>0?1:-1;
  if(f.stun>0||f.koT)return;
  if(aiT<=0){
    aiT=150+Math.random()*230;
    if(adx>140)aiMove=Math.sign(dx);
    else if(Math.random()<0.22)aiMove=-Math.sign(dx);else aiMove=0;
    f.blocking=(adx<95&&Math.random()<0.18);
    if(!f.blocking){
      if(adx<100&&Math.random()<0.7)tryAction(f,["LP","LP","HP","KK"][Math.floor(Math.random()*4)]);
      if(adx>=170&&f.cdS1<=0&&Math.random()<0.4)tryAction(f,"S1");
      if(adx<130&&f.cdS2<=0&&Math.random()<0.3)tryAction(f,"S2");
      if(f.en>=100&&Math.random()<0.5)tryAction(f,"ULT");
      if(Math.random()<0.1&&f.onG){f.vy=-13;f.onG=false;}
    }
  }
  f.vx=f.blocking?0:aiMove*3.2;
}

/* ================= LOOP ================= */
function loop(now){
  let dt=Math.min(42,now-lastT);lastT=now;frame++;
  if(slowmo>0){slowmo-=dt;dt*=0.32;}
  if(hitstop>0){hitstop-=dt;}
  else if(paused===0&&inBattle)update(dt);
  draw();
  raf=requestAnimationFrame(loop);
}
function update(dt){
  tAcc+=dt;
  if(tAcc>1000){tAcc-=1000;
    if(mode!=="online"||mySeat===1){timer--;if(mode==="online")send({t:"timer",v:timer});
      if(timer<=5&&timer>0)SFX.count();
      if(timer<=0){const w=(me.hp>=foe.hp)?me:foe;roundEnd(w);return;}}
  }
  for(const f of [me,foe]){
    const o=f===me?foe:me;
    if(f.comboT>0){f.comboT-=dt;if(f.comboT<=0)f.combo=0;}
    if(f.cdS1>0)f.cdS1-=dt;if(f.cdS2>0)f.cdS2-=dt;if(f.cdDG>0)f.cdDG-=dt;
    if(f.cool>0)f.cool-=dt;if(f.inv>0)f.inv-=dt;if(f.bubT>0)f.bubT-=dt;
    if(f.hurtT>0)f.hurtT-=dt;
    if(f.stun>0)f.stun-=dt;
    if(f===me&&!f.koT){
      if(f.stun<=0){
        f.blocking=!!keys.B&&f.onG&&f.atk<=0;
        f.vx=0;
        if(!f.blocking){
          if(keys.L){f.vx=-3.9;if(f.atk<=0)f.facing=-1;}
          if(keys.R){f.vx=3.9;if(f.atk<=0)f.facing=1;}
          if(keys.U&&f.onG){f.vy=-13.6;f.onG=false;SFX.jump();dust(f.x,GROUND,4);}
          if(keyEdge.DG&&f.cdDG<=0){f.cdDG=1500;f.inv=Math.max(f.inv,380);f.dash=(keys.L?-1:keys.R?1:f.facing)*10;SFX.dodge();dust(f.x,GROUND,6);}
          if(keyEdge.LP)tryAction(f,"LP");
          if(keyEdge.HP)tryAction(f,"HP");
          if(keyEdge.KK)tryAction(f,"KK");
          if(keyEdge.S1)tryAction(f,"S1");
          if(keyEdge.S2)tryAction(f,"S2");
          if(keyEdge.ULT)tryAction(f,"ULT");
        }
      } else f.blocking=false;
    } else if(mode!=="online"&&f===foe){
      aiUpdate(f,o,dt);
    } else if(f===foe){
      f.x+=(f.nx-f.x)*0.35;f.y+=(f.ny-f.y)*0.4;f.facing=f.nf||f.facing;
    }
    if(f.dash){f.x+=f.dash;f.dash*=0.8;if(Math.abs(f.dash)<0.4)f.dash=0;}
    if(f.atk>0){f.atk-=dt;
      if((mode!=="online"||f.local)&&!f.koT)meleeCheck(f,f===me?foe:me);
    }
    if(f===me||mode!=="online"){
      f.x+=f.vx;f.y+=f.vy;
      if(!f.onG)f.vy+=0.74;
      if(f.y>=GROUND){if(!f.onG&&f.vy>6)dust(f.x,GROUND,6);f.y=GROUND;f.vy=0;f.onG=true;}
      f.x=Math.max(36,Math.min(VW-36,f.x));
    }
  }
  for(const k in keyEdge)keyEdge[k]=false;
  if(mode!=="online"&&Math.abs(me.x-foe.x)<44&&!me.koT&&!foe.koT){const m=(me.x<foe.x)?-1:1;me.x+=m*1.4;foe.x-=m*1.4;}
  updateProjs(dt);
  if(mode==="online"){
    sendAcc+=dt;
    if(sendAcc>50){sendAcc=0;
      send({t:"st",x:Math.round(me.x),y:Math.round(me.y),f:me.facing,hp:me.hp,en:Math.round(me.en),b:me.blocking,
        a:{atk:me.atk>0?1:0,ty:me.atkType}});}
  }
  for(const p of fxList){p.life-=dt;
    if(p.t==="p"){p.x+=p.vx;p.y+=p.vy;p.vy+=0.3;}
    else if(p.t==="d")p.y-=0.6;
    else if(p.t==="r")p.r+=dt*p.grow;
    else if(p.t==="s"){p.x+=p.vx;p.y+=p.vy;p.vy+=0.35;p.rot+=0.2;}
    else if(p.t==="u"){p.x+=p.vx;p.y+=p.vy;}
  }
  fxList=fxList.filter(p=>p.life>0);
  if(bann){bann.t-=dt;if(bann.t<=0)bann=null;}
  if(flash>0)flash-=dt;
  if(shake>0)shake*=0.86;
  if(zoom>0)zoom*=0.93;
}

/* ================= DRAW ================= */
function initCheer(){
  cheerGirls=[{x:VW*0.5-46,col:"#ff5e9a",ph:0},{x:VW*0.5,col:"#ffd23a",ph:1.2},{x:VW*0.5+46,col:"#5ec8ff",ph:2.3}];
}
function drawBG(){
  const t=frame/60;
  const g=ctx.createLinearGradient(0,0,0,VH);
  g.addColorStop(0,"#0a1030");g.addColorStop(.5,"#1a2150");g.addColorStop(.85,"#3a2a55");g.addColorStop(1,"#241a35");
  ctx.fillStyle=g;ctx.fillRect(0,0,VW,VH);
  ctx.fillStyle="rgba(255,255,255,.7)";
  for(let i=0;i<40;i++){const sx=(i*173)%VW,sy=(i*97)%(GROUND-160);ctx.globalAlpha=(0.4+0.6*Math.abs(Math.sin(t*2+i)))*0.8;ctx.fillRect(sx,sy,2,2);}
  ctx.globalAlpha=1;
  ctx.fillStyle="#141a3c";
  for(let i=0;i<12;i++){const bw=50+(i*37)%60,bh=70+(i*53)%120;ctx.fillRect(i*84-20,GROUND-150-bh,bw,bh+150);}
  ctx.fillStyle="rgba(255,210,100,.5)";
  for(let i=0;i<60;i++){const wx=(i*61)%VW,wy=GROUND-260+(i*37)%180;if(Math.sin(i*3+t)>0)ctx.fillRect(wx,wy,4,5);}
  ctx.fillStyle="#23284e";ctx.fillRect(VW*0.32,GROUND-250,VW*0.36,250);
  ctx.fillStyle="#2e3464";ctx.fillRect(VW*0.30,GROUND-262,VW*0.40,16);
  const glow=0.6+0.4*Math.sin(t*2.2);
  ctx.save();ctx.shadowColor="rgba(90,170,255,"+glow+")";ctx.shadowBlur=18;
  ctx.fillStyle="#9fd4ff";ctx.font="bold 26px 'STKaiti','KaiTi','Microsoft YaHei'";ctx.textAlign="center";
  ctx.fillText("梅 州 开 放 大 学",VW*0.5,GROUND-218);ctx.restore();
  ctx.fillStyle="#06101e";ctx.fillRect(VW*0.36,GROUND-196,VW*0.28,52);
  ctx.strokeStyle="#3a8bd8";ctx.lineWidth=2;ctx.strokeRect(VW*0.36,GROUND-196,VW*0.28,52);
  ctx.save();ctx.beginPath();ctx.rect(VW*0.36+3,GROUND-193,VW*0.28-6,46);ctx.clip();
  ctx.fillStyle="#33d2ff";ctx.font="bold 20px 'Microsoft YaHei'";ctx.textAlign="left";
  const msg="◆ 荣耀擂台 ◆ 开放教育 智慧梅州 ◆ 第一帅哥保卫战 ";
  const off=(t*70)%560;
  ctx.fillText(msg,VW*0.36+8-off,GROUND-162);ctx.fillText(msg,VW*0.36+8-off+560,GROUND-162);ctx.restore();
  ctx.strokeStyle="rgba(255,160,90,.35)";ctx.lineWidth=3;
  for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(VW*0.16,GROUND-10,40+i*16,Math.PI,0);ctx.stroke();
    ctx.beginPath();ctx.arc(VW*0.84,GROUND-10,40+i*16,Math.PI,0);ctx.stroke();}
  for(let i=0;i<6;i++){
    const fxp=80+i*150,wob=Math.sin(t*3+i)*8;
    ctx.strokeStyle="#777";ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(fxp,GROUND-120);ctx.lineTo(fxp,GROUND-66);ctx.stroke();
    ctx.fillStyle=i%2?"#d5261b":"#1f63b8";
    ctx.beginPath();ctx.moveTo(fxp,GROUND-120);ctx.quadraticCurveTo(fxp+18+wob,GROUND-114,fxp+34+wob,GROUND-108);ctx.lineTo(fxp,GROUND-100);ctx.fill();
  }
  for(let i=0;i<16;i++){
    const px=(i*131+t*26)%VW,py=GROUND-40-((i*71+t*14)%200);
    ctx.fillStyle=i%2?"rgba(90,170,255,.5)":"rgba(255,150,80,.45)";
    ctx.beginPath();ctx.arc(px,py,2.2,0,7);ctx.fill();
  }
  ctx.save();ctx.globalAlpha=0.1;ctx.fillStyle="#bcd9ff";
  const sw=Math.sin(t*0.7)*VW*0.25;
  ctx.beginPath();ctx.moveTo(VW*0.5+sw,0);ctx.lineTo(VW*0.32+sw,GROUND);ctx.lineTo(VW*0.68+sw,GROUND);ctx.fill();ctx.restore();
  ctx.fillStyle="#2c2436";ctx.fillRect(0,GROUND,VW,VH-GROUND);
  const fg=ctx.createLinearGradient(0,GROUND,0,GROUND+24);
  fg.addColorStop(0,"#4a3a55");fg.addColorStop(1,"#2c2436");
  ctx.fillStyle=fg;ctx.fillRect(0,GROUND,VW,24);
  ctx.strokeStyle="rgba(90,170,255,"+(0.5+0.3*Math.sin(t*3))+")";ctx.lineWidth=4;
  ctx.beginPath();ctx.moveTo(VW*0.1,GROUND+4);ctx.lineTo(VW*0.9,GROUND+4);ctx.stroke();
  ctx.strokeStyle="rgba(255,120,70,"+(0.5+0.3*Math.cos(t*3))+")";
  ctx.beginPath();ctx.moveTo(VW*0.1,GROUND+34);ctx.lineTo(VW*0.9,GROUND+34);ctx.stroke();
  ctx.fillStyle="rgba(255,255,255,.16)";ctx.font="bold 15px 'Microsoft YaHei'";ctx.textAlign="center";
  ctx.fillText("梅州开放大学 · 荣耀擂台",VW*0.5,GROUND+26);
  if(cine||flash>0){ctx.fillStyle="rgba(5,2,18,"+(cine?0.55:Math.min(0.4,flash/850))+")";ctx.fillRect(0,0,VW,VH);}
}
function drawCheer(c){
  const t=frame/60,b=Math.abs(Math.sin(t*4+c.ph))*8,up=Math.sin(t*4+c.ph)>0;
  const x=c.x,y=GROUND+2-b;
  ctx.save();ctx.translate(x,y);ctx.scale(0.6,0.6);
  function pom(px,py){ctx.fillStyle=c.col;for(let a=0;a<8;a++){const an=a/8*6.28+t*6;ctx.beginPath();ctx.ellipse(px+Math.cos(an)*7,py+Math.sin(an)*7,5,5,0,0,7);ctx.fill();}ctx.fillStyle="#fff";ctx.beginPath();ctx.arc(px,py,4,0,7);ctx.fill();}
  ctx.strokeStyle="#e8b07a";ctx.lineWidth=7;ctx.lineCap="round";
  ctx.beginPath();ctx.moveTo(-5,-30);ctx.lineTo(-8,2);ctx.stroke();ctx.beginPath();ctx.moveTo(5,-30);ctx.lineTo(8,2);ctx.stroke();
  ctx.fillStyle=c.col;ctx.beginPath();ctx.moveTo(-16,-30);ctx.lineTo(16,-30);ctx.lineTo(11,-12);ctx.lineTo(-11,-12);ctx.closePath();ctx.fill();
  ctx.fillStyle="#fff";for(let i=-12;i<14;i+=8){ctx.beginPath();ctx.moveTo(i,-30);ctx.lineTo(i+3,-14);ctx.lineTo(i+5,-30);ctx.fill();}
  ctx.fillStyle="#fff";ctx.beginPath();ctx.roundRect(-13,-58,26,30,7);ctx.fill();
  ctx.fillStyle=c.col;ctx.fillRect(-13,-44,26,5);
  ctx.strokeStyle="#e8b07a";ctx.lineWidth=6;
  if(up){ctx.beginPath();ctx.moveTo(-11,-54);ctx.lineTo(-20,-74);ctx.stroke();ctx.beginPath();ctx.moveTo(11,-54);ctx.lineTo(20,-74);ctx.stroke();pom(-22,-78);pom(22,-78);}
  else{ctx.beginPath();ctx.moveTo(-11,-54);ctx.lineTo(-22,-44);ctx.stroke();ctx.beginPath();ctx.moveTo(11,-54);ctx.lineTo(22,-44);ctx.stroke();pom(-24,-42);pom(24,-42);}
  ctx.fillStyle="#f3cba6";ctx.beginPath();ctx.arc(0,-70,12,0,7);ctx.fill();
  ctx.fillStyle="#5a3a22";ctx.beginPath();ctx.arc(0,-74,12,Math.PI,0);ctx.fill();ctx.fillRect(-12,-74,4,16);ctx.fillRect(8,-74,4,16);
  ctx.strokeStyle="#a03b2a";ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,-68,4,0.2,Math.PI-0.2);ctx.stroke();
  ctx.fillStyle="#222";ctx.beginPath();ctx.arc(-4,-72,1.4,0,7);ctx.arc(4,-72,1.4,0,7);ctx.fill();
  ctx.restore();
}
/* --- the real-person fighter renderer --- */
function drawFighter(f){
  const c=CHARS[f.ci],t=performance.now()/1000;
  const img=c.body();if(!img.complete||!img.naturalWidth)return;
  const H=c.h, W=H*img.naturalWidth/img.naturalHeight;
  const mv=f.atk>0?curMove(f):null;
  const prog=mv?1-(f.atk/f.atkDur):0;
  const atkPulse=mv?Math.sin(Math.min(1,prog*1.6)*Math.PI):0;
  // pose params
  let lean=0,lungeX=0,sclX=1,sclY=1,rot=0;
  if(f.koT){rot=f.facing* -1.4;lean=0;}
  else if(f.stun>0){rot=Math.sin(t*40)*0.04 - f.facing*0.12;}
  else if(mv){lean=(mv.lean||0.2)*atkPulse;lungeX=(mv.lunge||0)*atkPulse;
    if(f.atkType==="SPIN")rot=prog*12.56*f.facing; // two full spins
    if(f.atkType==="SHO")rot=-f.facing*0.25*atkPulse;
    sclX=1+0.06*atkPulse;}
  else if(f.blocking){lean=-0.1;sclY=0.97;}
  else if(!f.onG){rot=f.facing*0.08;}
  else if(Math.abs(f.vx)>0.5){lean=f.facing*Math.sign(f.vx)*0.5>0?0.12:-0.1;sclY=1+0.02*Math.sin(t*16);}
  else {sclY=1+0.015*Math.sin(t*3+f.ci);} // idle breathing
  const x=f.x+f.facing*lungeX, y=f.y;
  // shadow
  ctx.fillStyle="rgba(0,0,0,.32)";ctx.beginPath();ctx.ellipse(f.x,GROUND+4,W*0.42,8,0,0,7);ctx.fill();
  ctx.save();ctx.translate(x,y);
  ctx.rotate((lean+rot)*(f.koT?1:f.facing===1?1:1)); // lean sign handled below by flip
  ctx.scale(f.facing*sclX,sclY);
  if(f.inv>0&&!f.koT&&Math.floor(t*20)%2===0)ctx.globalAlpha=0.55;
  // energy aura when full
  if(f.en>=100&&!f.koT){
    ctx.save();ctx.shadowColor=c.main;ctx.shadowBlur=26+10*Math.sin(t*9);
    ctx.drawImage(img,-W/2,-H,W,H);ctx.restore();
  }
  // dash/special motion streak
  if(mv&&(f.atkType==="KK"||f.atkType==="SPIN"||f.atkType==="SHO")){
    ctx.save();ctx.globalAlpha=0.3;
    ctx.drawImage(img,-W/2-14,-H,W,H);
    ctx.globalAlpha=0.15;ctx.drawImage(img,-W/2-28,-H,W,H);
    ctx.restore();
  }
  // body
  ctx.drawImage(img,-W/2,-H,W,H);
  // hurt red flash overlay
  if(f.hurtT>0&&c.hurt()){ctx.globalAlpha=Math.min(0.85,f.hurtT/240);ctx.drawImage(c.hurt(),-W/2,-H,W,H);ctx.globalAlpha=1;}
  // white flash during ult windup
  if(mv&&f.atkType==="ULTM"&&c.white()){ctx.globalAlpha=0.5+0.4*Math.sin(t*22);ctx.drawImage(c.white(),-W/2,-H,W,H);ctx.globalAlpha=1;}
  // energy fist/foot projection on strikes
  if(mv&&atkPulse>0.35&&f.atkType!=="ULTM"){
    const fy=(f.atkType==="KK"||f.atkType==="SPIN")?-H*0.28:-H*0.62;
    const fxx=W*0.5+18*atkPulse;
    const r=(f.atkType==="LP3"||f.atkType==="HP")?20:14;
    const grd=ctx.createRadialGradient(fxx,fy,2,fxx,fy,r*2);
    grd.addColorStop(0,"#fff");grd.addColorStop(0.5,c.spark);grd.addColorStop(1,c.glow+"0)");
    ctx.fillStyle=grd;ctx.beginPath();ctx.arc(fxx,fy,r*2,0,7);ctx.fill();
  }
  // SHO rising trail
  if(mv&&f.atkType==="SHO"){
    ctx.strokeStyle=c.glow+"0.8)";ctx.lineWidth=6;
    ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(W*0.4,-H*0.5,W*0.55,-H*1.05);ctx.stroke();
  }
  // block shield
  if(f.blocking){ctx.strokeStyle=c.glow+(0.6+0.3*Math.sin(t*10))+")";ctx.lineWidth=5;
    ctx.beginPath();ctx.arc(W*0.42,-H*0.5,H*0.42,-1.15,1.15);ctx.stroke();}
  ctx.restore();
  drawOverhead(f,W);
  if(f.bubT>0){ctx.font="bold 14px 'Microsoft YaHei'";const tw=ctx.measureText(f.bubble).width+18;
    ctx.fillStyle="rgba(255,255,255,.95)";ctx.beginPath();ctx.roundRect(f.x-tw/2,y-c.h-78,tw,28,14);ctx.fill();
    ctx.fillStyle="#c0392b";ctx.textAlign="center";ctx.fillText(f.bubble,f.x,y-c.h-59);}
}
function drawOverhead(f,W){
  const c=CHARS[f.ci],x=f.x,top=f.y-c.h-44;
  const bw=78,bh=8;
  ctx.font="bold 13px 'Microsoft YaHei'";ctx.textAlign="center";
  ctx.fillStyle="rgba(0,0,0,.6)";ctx.fillText(c.name,x+1,top-11);
  ctx.fillStyle=c.main;ctx.fillText(c.name,x,top-12);
  ctx.fillStyle="rgba(0,0,0,.55)";ctx.beginPath();ctx.roundRect(x-bw/2,top,bw,bh,4);ctx.fill();
  const w=bw*Math.max(0,f.hp)/100;
  ctx.fillStyle=f.hp>40?"#46d160":(f.hp>18?"#ffb02e":"#ff4d4d");
  if(w>0){ctx.beginPath();ctx.roundRect(x-bw/2,top,w,bh,4);ctx.fill();}
  ctx.strokeStyle="#fff";ctx.lineWidth=1.5;ctx.beginPath();ctx.roundRect(x-bw/2,top,bw,bh,4);ctx.stroke();
  ctx.fillStyle="rgba(0,0,0,.55)";ctx.fillRect(x-bw/2,top+bh+2,bw,4);
  ctx.fillStyle=f.en>=100?"#ffd23a":"#9a7bff";ctx.fillRect(x-bw/2,top+bh+2,bw*f.en/100,4);
  if(f.en>=100){ctx.fillStyle="#ffd23a";ctx.font="bold 9px sans-serif";ctx.fillText("大招就绪",x,top+bh+16);}
}
function drawHUD(){
  ctx.fillStyle="rgba(0,0,0,.55)";ctx.beginPath();ctx.roundRect(VW/2-32,8,64,36,8);ctx.fill();
  ctx.fillStyle=timer<=10?"#ff4d4d":"#ffd23a";ctx.font="bold 25px 'Microsoft YaHei'";ctx.textAlign="center";
  ctx.fillText(Math.max(0,timer),VW/2,35);
  for(let i=0;i<2;i++){
    ctx.fillStyle=i<wins[0]?"#ffd23a":"rgba(255,255,255,.25)";
    ctx.beginPath();ctx.arc(VW/2-50-i*16,26,6,0,7);ctx.fill();
    ctx.fillStyle=i<wins[1]?"#ffd23a":"rgba(255,255,255,.25)";
    ctx.beginPath();ctx.arc(VW/2+50+i*16,26,6,0,7);ctx.fill();
  }
  function ava(f,x){
    const c=CHARS[f.ci];
    if(c.face.complete&&c.face.naturalWidth){
      ctx.save();ctx.beginPath();ctx.arc(x,30,20,0,7);ctx.clip();ctx.drawImage(c.face,x-20,10,40,40);ctx.restore();}
    ctx.strokeStyle=c.main;ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,30,20,0,7);ctx.stroke();
  }
  ava(me.ci===0?me:foe,34);ava(me.ci===0?foe:me,VW-34);
  if(me.combo>=2&&me.comboT>0){
    ctx.save();ctx.translate(VW*0.5,110);ctx.rotate(-0.06);
    ctx.font="bold 40px 'Microsoft YaHei'";ctx.textAlign="center";
    ctx.fillStyle="rgba(0,0,0,.5)";ctx.fillText(me.combo+" COMBO",3,3);
    ctx.fillStyle="#ffd23a";ctx.fillText(me.combo+" COMBO",0,0);ctx.restore();
  }
}
function drawCine(){
  if(!cine)return;
  const p=1-cine.t/cine.d;cine.t-=16;
  ctx.fillStyle="rgba(4,2,16,.8)";ctx.fillRect(0,0,VW,VH);
  ctx.strokeStyle="rgba(255,255,255,.25)";ctx.lineWidth=2;
  for(let i=0;i<24;i++){const a=i/24*6.28;ctx.beginPath();ctx.moveTo(VW/2+Math.cos(a)*120,VH/2+Math.sin(a)*70);ctx.lineTo(VW/2+Math.cos(a)*VW,VH/2+Math.sin(a)*VW);ctx.stroke();}
  const cx=VW*0.32+Math.min(1,p*3)*VW*0.05,R=112;
  if(cine.c.face.complete&&cine.c.face.naturalWidth){
    ctx.save();ctx.beginPath();ctx.arc(cx,VH*0.46,R,0,7);ctx.clip();
    ctx.drawImage(cine.c.face,cx-R,VH*0.46-R,R*2,R*2);ctx.restore();}
  ctx.strokeStyle=cine.c.main;ctx.lineWidth=7;ctx.beginPath();ctx.arc(cx,VH*0.46,R,0,7);ctx.stroke();
  ctx.strokeStyle=cine.c.glow+"0.55)";ctx.lineWidth=14;ctx.beginPath();ctx.arc(cx,VH*0.46,R+14,0,7);ctx.stroke();
  ctx.textAlign="left";
  ctx.font="bold 48px 'STKaiti','KaiTi','Microsoft YaHei'";
  ctx.fillStyle="rgba(0,0,0,.6)";ctx.fillText(cine.c.ult,VW*0.48+4,VH*0.42+4);
  ctx.fillStyle=cine.c.main;ctx.fillText(cine.c.ult,VW*0.48,VH*0.42);
  ctx.font="bold 22px 'Microsoft YaHei'";ctx.fillStyle="#ffd23a";
  ctx.fillText("ULTIMATE!",VW*0.48,VH*0.52);
  for(let i=0;i<10;i++){const a=Math.random()*6.28,r=140+Math.random()*120;
    ctx.fillStyle=cine.c.spark;ctx.globalAlpha=0.7;
    ctx.beginPath();ctx.arc(cx+Math.cos(a)*r*(1-p),VH*0.46+Math.sin(a)*r*(1-p),3,0,7);ctx.fill();ctx.globalAlpha=1;}
}
function drawStarShape(cx2,cy,sp,outer,inner){ctx.beginPath();for(let i=0;i<sp*2;i++){const r=i%2?inner:outer,a=i*Math.PI/sp-Math.PI/2;ctx.lineTo(cx2+Math.cos(a)*r,cy+Math.sin(a)*r);}ctx.closePath();ctx.fill();}
function draw(){
  ctx.save();
  if(zoom>0.02){const z=1+zoom*0.08;ctx.translate(VW/2,VH*0.6);ctx.scale(z,z);ctx.translate(-VW/2,-VH*0.6);}
  if(shake>1)ctx.translate((Math.random()-0.5)*shake,(Math.random()-0.5)*shake);
  drawBG();
  cheerGirls.forEach(drawCheer);
  if(me&&foe){[me,foe].forEach(drawFighter);}
  projs.forEach(drawProj);
  for(const p of fxList){
    if(p.t==="p"){ctx.fillStyle=p.color;ctx.globalAlpha=Math.max(0,p.life/430);ctx.beginPath();ctx.arc(p.x,p.y,4,0,7);ctx.fill();ctx.globalAlpha=1;}
    else if(p.t==="r"){ctx.strokeStyle=p.color;ctx.globalAlpha=Math.max(0,p.life/520);ctx.lineWidth=3;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.stroke();ctx.globalAlpha=1;}
    else if(p.t==="d"){ctx.font=(p.crit?"bold 30px":"bold 19px")+" 'Microsoft YaHei'";ctx.fillStyle=p.crit?"#ffd23a":"#ff5a3a";ctx.textAlign="center";ctx.globalAlpha=Math.max(0,p.life/780);ctx.fillText(p.v,p.x,p.y);ctx.globalAlpha=1;}
    else if(p.t==="s"){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.globalAlpha=Math.max(0,p.life/660);ctx.fillStyle=p.col;drawStarShape(0,0,5,8,3.5);ctx.restore();ctx.globalAlpha=1;}
    else if(p.t==="u"){ctx.fillStyle="rgba(180,170,160,"+Math.max(0,p.life/380)*0.6+")";ctx.beginPath();ctx.arc(p.x,p.y,5,0,7);ctx.fill();}
    else if(p.t==="sl"){const a=Math.max(0,p.life/240);ctx.strokeStyle=p.col;ctx.globalAlpha=a;ctx.lineWidth=5*a+1;
      ctx.beginPath();ctx.moveTo(p.x-30*p.dir,p.y+26);ctx.lineTo(p.x+34*p.dir,p.y-26);ctx.stroke();ctx.globalAlpha=1;}
  }
  if(me&&foe)drawHUD();
  drawCine();
  if(bann){
    const k=Math.min(1,(bann.d-bann.t)/160);
    ctx.save();ctx.translate(VW/2,VH/2-46);ctx.scale(0.6+0.4*k,0.6+0.4*k);
    ctx.font="bold "+(bann.text.length>8?36:56)+"px 'STKaiti','KaiTi','Microsoft YaHei'";
    ctx.textAlign="center";ctx.shadowColor="rgba(0,0,0,.8)";ctx.shadowBlur=16;
    ctx.fillStyle=bann.color;ctx.fillText(bann.text,0,0);ctx.shadowBlur=0;ctx.restore();
  }
  if(flash>0){ctx.fillStyle="rgba(255,255,255,"+Math.min(0.85,flash/340)+")";ctx.fillRect(0,0,VW,VH);}
  ctx.restore();
  if(me){
    setCd("cdS1",me.cdS1,2600);setCd("cdS2",me.cdS2,4200);setCd("cdDG",me.cdDG,1500);
    const u=document.getElementById("bULT");
    u.classList.toggle("ready",me.en>=100);u.classList.toggle("dis",me.en<100);
  }
}
function setCd(id,v,max){document.getElementById(id).style.setProperty("--p",Math.max(0,Math.min(100,v/max*100))+"%");}

/* ================= SCREENS ================= */
function showScr(id){
  ["scrLoad","scrMenu","scrHelp","scrJoin","scrRoom","scrRes"].forEach(s=>document.getElementById(s).classList.add("hide"));
  if(id)document.getElementById(id).classList.remove("hide");
}
function toast(t){const el=document.getElementById("toast");el.textContent=t;el.style.opacity=1;clearTimeout(el._t);el._t=setTimeout(()=>el.style.opacity=0,2800);}

document.getElementById("btnHost").onclick=()=>{resumeAudio();SFX.click();hostRoom();};
document.getElementById("btnJoin").onclick=()=>{resumeAudio();SFX.click();showScr("scrJoin");};
document.getElementById("btnJoinGo").onclick=()=>{const v=document.getElementById("joinCode").value.trim().toUpperCase();if(v.length>=3){SFX.click();joinRoom(v);}else toast("请输入房间号");};
document.getElementById("btnJoinBack").onclick=()=>showScr("scrMenu");
document.getElementById("btnSolo").onclick=()=>{resumeAudio();SFX.click();mode="solo";online=false;beginBattle("solo");};
document.getElementById("btnHelp").onclick=()=>{SFX.click();showScr("scrHelp");};
document.getElementById("btnHelpBack").onclick=()=>showScr("scrMenu");
document.getElementById("btnShareRoom").onclick=shareRoom;
document.getElementById("btnReady").onclick=()=>{
  SFX.click();
  if(socket)socket.emit("ready",true);
  document.getElementById(mySeat===1?"pc1":"pc2").classList.add("rdy");
  document.getElementById(mySeat===1?"pc1s":"pc2s").textContent="已准备 ✔";
  document.getElementById("btnReady").textContent="✅ 已准备，等待对方…";
};
document.getElementById("btnRoomBack").onclick=()=>{
  if(socket){try{socket.disconnect();}catch(e){}socket=null;}
  online=false;inRoom=false;netStat("",false);showScr("scrMenu");
};
document.getElementById("btnAgain").onclick=()=>{
  SFX.click();
  if(mode==="online"&&online){
    if(socket)socket.emit("rematch");
    showScr("scrRoom");
    resetReadyUI();
    document.getElementById("btnReady").classList.remove("hide");
    document.getElementById("pc1s").textContent=mySeat===1?"已就位":"房主";
    document.getElementById("pc2s").textContent="已加入";
    toast("已发起再战！双方点击准备即可重开");
  } else beginBattle("solo");
};
document.getElementById("btnMenu2").onclick=()=>{
  if(socket){try{socket.disconnect();}catch(e){}socket=null;}
  online=false;inRoom=false;netStat("",false);showScr("scrMenu");
};
document.getElementById("btnShare2").onclick=()=>{
  const url=location.origin+location.pathname;
  const data={title:"梅开格斗：开放之战",text:"我刚在梅州开放大学·荣耀擂台打出 "+stats.maxCombo+" 连击！罗一帅 VS 杨二帅，敢来挑战吗？",url};
  if(navigator.share){navigator.share(data).catch(()=>{});}
  else{try{navigator.clipboard.writeText(data.text+" "+url);}catch(e){}toast("战绩已复制，去微信粘贴吧！");}
};

/* loading + ?room= auto join */
let ldp=0;
const ldt=setInterval(()=>{
  ldp+=18+Math.random()*16;
  document.getElementById("ldfill").style.width=Math.min(100,ldp)+"%";
  if(ldp>=100){clearInterval(ldt);
    const m=location.search.match(/room=([A-Za-z0-9]{3,8})/);
    if(m){joinRoom(m[1].toUpperCase());}
    else showScr("scrMenu");
    document.getElementById("sndTog").classList.remove("hide");
  }
},160);
